/*
	Gratitude // 5.6.2023
	#minacoding #p5js #generativeart #dailycoding
 */

let circs = [];
let maxr, maxd;
let font, fSize, texts;

function preload() {
  font = loadFont('https://openprocessing.org/sketch/1947325/files/KleeOne-SemiBold.ttf'); // https://fonts.google.com/specimen/Klee+One
}

function setup() {
	createCanvas(windowWidth, windowHeight);
	pixelDensity(1);
	frameRate(60);
	maxd = max(width, height) * 0.5;
	maxr = maxd * 0.3;

	circs.push({x: 0, y:0, r: maxr * 0.35, d: 0});

	// preevaluate text sizes
	preEvaluateTexts();
}

function draw() {
	background("beige");
	translate(width / 2, height / 2);
	stroke(128, 128)
	noFill();
	// circle(0, 0, maxr + maxr)

	// circle packing
	const a = random(TWO_PI);
	const d = random(maxr);
	const r = map(d, 0, maxr, max(1, maxr * 0.5 - frameCount * 0.01), 3);
	const x = cos(a) * d;
	const y = sin(a) * d;
	let isOverlapping = false;
	for (let c of circs) {
		isOverlapping = isOverlapping || dist(x, y, c.x, c.y) < (r + c.r) * 0.5
	}
	if (!isOverlapping) circs.push({x, y, r, d});

	for (let c of circs) {
		stroke(192, 32, 64, map(c.d, 0, maxr, 128, 20));
		circle(c.x, c.y, c.r);
	}


	const sizeHeart = maxr * min(0.7, max(0.3, abs(sin(frameCount * 0.05))))
	drawHeart(sizeHeart);
	drawTexts();
	// // noLoop() removed for animation
}

function drawHeart(r) {
	push();
	noStroke()
	// strokeWeight(2);
	fill(192, 8, 32, 128);

	beginShape();
	for (let t = 0; t < TWO_PI; t += 0.1) {
		var x = 16 * sin(t) * sin(t) * sin(t);
		var y = 13 * cos(t) - 5 * cos(2 * t) - 2 * cos(3 * t) - cos(4 * t)
		x *= r / 16
		y *= r / -16
		vertex(x, y);
	}
	endShape(CLOSE);
	pop();
}

function drawTexts() {
	push();
	colorMode(HSB, 100);
	textAlign(LEFT, CENTER);
	const da = TWO_PI / texts.length;
	rotate(frameCount * 0.01) // different start angles
	for (i = 0, a = 0; i < texts.length; i++, a += da) {
		// for all texts
		noStroke();
		fill(map(a, 0, TWO_PI, 0, 100), 75, 50)
		// textSize(16 + 16 * (scl - 1) * sin(a + frameCount * 0.02) * noise(i * 0.01, frameCount * 0.015));
		textSize(fSize*0.66 + fSize*0.33 * sin(a + frameCount * 0.02)); // alter sizes
		text(texts[i], maxr, 0); // print it out after the circle packing
		rotate(da); // rotate for next text
	}
	pop();
}

function preEvaluateTexts() {
	texts = [
		"Gemeinsame Zeit", "Time together", "一緒に過ごす時間", 
		"Unsere Kinder", "Our children", "子どもたち", 
		"Inspiration", "Inspiration", "インスピレーション", 
		"Freiräume", "Freedom", "自由", 
		"Veränderungen", "Change","変化", 
		"Diskurs", "Discourse",  "議論", 
		"Erfahrungen", "Experiences", "体験", 
		"Erlebnisse in der Natur","Outdoor activities", "自然の中での体験", 
		"Unterstützung", "Support", "サポート", 
		"Urlaube und Ausflüge", "Holidays and excursions", "休暇・小旅行"
	];

	let maxTW = 0;
	fSize = 16; // best guess
	textFont(font);
	for (let t of texts) {
		let currTB = font.textBounds(t, 0, 0, fSize); // textBounds(line, x, y, [fontSize], [options])
		if (currTB.w > maxTW) maxTW = currTB.w;
	}
	fSize *= maxd /maxTW;
}

function windowResized() {
	setup();
}
